1: //! rollout 档案 → 可索引语义文档（SH-113）。
2: //!
3: //! 口径对齐上游 `session-query/src/extraction.ts` + `documents.ts`，但输入是
4: //! **SHANIU 的持久化事实源**（`rollout::RolloutItem` / `model_client::HistoryItem`），
5: //! 不是 DSH journal 事件。推导链与 `lib.rs::project_entries`（`load_session`
6: //! 回放路径）同源：先建 `call_id → output` 索引，再按原序投影，工具输出并进
7: //! 自己的调用，压缩锚点作为用户消息文本。因此**同一份档案**在「实时写入后」
8: //! 与「重启回放后」抽出的文档序列逐项一致（SH-108 的推导范式）。
9: //!
10: //! 与上游 host `list.ts` 的一处有意偏差：上游只把 `user/message` / `assistant/message`
11: //! 的 bestMatch 交给侧栏；SH-113 卡验收明确要求「命中正文与工具输出片段」，
12: //! 故 `tool/call` 与 `tool/result` 也产文档、也参与排名。
13: 
14: use std::collections::{HashMap, HashSet};
15: 
16: use crate::model_client::{HistoryItem, Role};
17: use crate::rollout::RolloutItem;
18: use crate::session_query::query::fts_text;
19: 
20: /// 一条可索引语义文档（对应 FTS5 `persisted_docs` / `temp.live_docs` 的一行）。
21: #[derive(Debug, Clone, PartialEq, Eq)]
22: pub struct SearchDoc {
23:     /// 档案内稳定的文档序号：一个条目最多展开成两条（调用 + 输出），故用 `index*2`。
24:     pub seq: i64,
25:     /// 事件语义类型（DSH 词汇表同款拼写，便于与上游对照）。
26:     pub doc_type: &'static str,
27:     /// 兜底排序时间：档案 created_at + seq（rollout 没有逐条时间戳，不伪造墙钟）。
28:     pub time: i64,
29:     /// 该段内容在**当前上下文**里的位置：
30:     /// - `current`：仍在模型看得到的历史里；
31:     /// - `shadowed`：已被压缩锚点取代——档案里还在、能搜到，但模型当前不再看到。
32:     ///
33:     /// 「能查到」与「还在生效」是两件事，搜索命中时必须能区分（否则用户会以为
34:     /// 模型还记得那段，并基于这个假设做判断）。
35:     pub surface: &'static str,
36:     /// 已 `fts_text()` 归一化、可直接写入 FTS5 的文本。
37:     pub text: String,
38:     /// 按 Unicode 码点计的文档长度（排名用「文档短者优先」）。
39:     pub codepoint_length: i64,
40: }
41: 
42: /// 从一份档案的条目序列抽取全部可搜索文档；空文本不入库。
43: pub fn build_documents(items: &[RolloutItem], created_at: u64) -> Vec<SearchDoc> {
44:     // 与 lib.rs::project_entries 同一份配对规则：档案里输出排在调用之后，按 call_id 归位。
45:     // 同时记住输出的档案下标，供 `surface` 判定（调用与输出可能落在压缩区间两侧）。
46:     let mut outputs: HashMap<String, (String, usize)> = HashMap::new();
47:     for (index, item) in items.iter().enumerate() {
48:         if let RolloutItem::ResponseItem {
49:             item: HistoryItem::FunctionCallOutput { call_id, output },
50:             ..
51:         } = item
52:         {
53:             outputs.insert(call_id.clone(), (output.clone(), index));
54:         }
55:     }
56:     let shadowed = shadowed_indices(items);
57:     let surface_of = |index: usize| {
58:         if shadowed.contains(&index) {
59:             "shadowed"
60:         } else {
61:             "current"
62:         }
63:     };
64: 
65:     let mut documents = Vec::new();
66:     for (index, item) in items.iter().enumerate() {
67:         let base_seq = (index as i64) * 2;
68:         let push = |text: String,
69:                     doc_type: &'static str,
70:                     seq: i64,
71:                     surface: &'static str,
72:                     documents: &mut Vec<SearchDoc>| {
73:             if text.is_empty() {
74:                 return;
75:             }
76:             let indexed = fts_text(&text);
77:             if indexed.is_empty() {
78:                 return;
79:             }
80:             let codepoint_length = indexed.chars().count() as i64;
81:             documents.push(SearchDoc {
82:                 seq,
83:                 doc_type,
84:                 time: created_at as i64 + seq,
85:                 surface,
86:                 text: indexed,
87:                 codepoint_length,
88:             });
89:         };
90: 
91:         match item {
92:             RolloutItem::ResponseItem {
93:                 item: HistoryItem::Message { role, text, .. },
94:                 ..
95:             } => {
96:                 // reasoning_content 是模型协议回放字段，不是用户可见语义文本
97:                 // （上游 extraction.ts 的 reasoning block 明确返回 []），不进索引。
98:                 push(
99:                     join_text(&[text.trim()]),
100:                     role_doc_type(*role),
101:                     base_seq,
102:                     surface_of(index),
103:                     &mut documents,
104:                 );
105:             }
106:             RolloutItem::ResponseItem {
107:                 item: HistoryItem::FunctionCall { name, arguments, call_id },
108:                 ..
109:             } => {
110:                 push(
111:                     join_text(&[name.trim(), arguments.trim()]),
112:                     "tool/call",
113:                     base_seq,
114:                     surface_of(index),
115:                     &mut documents,
116:                 );
117:                 if let Some((output, output_index)) = outputs.get(call_id) {
118:                     push(
119:                         join_text(&[output.trim()]),
120:                         "tool/result",
121:                         base_seq + 1,
122:                         surface_of(*output_index),
123:                         &mut documents,
124:                     );
125:                 }
126:             }
127:             // 输出已并进它自己的调用，不单独成条（与回放投影一致）。
128:             RolloutItem::ResponseItem {
129:                 item: HistoryItem::FunctionCallOutput { .. },
130:                 ..
131:             } => {}
132:             // 压缩锚点的语义就是「用摘要取代区间」：摘要本身是新的当前内容，
133:             // 被它取代的原文才转成 shadowed（见 `shadowed_indices`）。
134:             RolloutItem::Compacted { summary, .. } => {
135:                 push(
136:                     join_text(&[summary.trim()]),
137:                     "user/message",
138:                     base_seq,
139:                     "current",
140:                     &mut documents,
141:                 );
142:             }
143:             // 带图消息只索引文字与图片路径：字节不在档案里，索引也没得可索引。
144:             RolloutItem::ResponseItem {
145:                 item: HistoryItem::ImageMessage { role, text, images },
146:                 ..
147:             } => {
148:                 let paths = images
149:                     .iter()
150:                     .map(|image| image.path.as_str())
151:                     .collect::<Vec<_>>();
152:                 let mut parts = vec![text.trim()];
153:                 parts.extend(paths);
154:                 push(
155:                     join_text(&parts),
156:                     role_doc_type(*role),
157:                     base_seq,
158:                     surface_of(index),
159:                     &mut documents,
160:                 );
161:             }
162:             // 首行 meta、子代理引用、档位事件、退出留痕与回合结局都不是可搜索内容。
163:             // 系统提示词也不进索引：它是宿主拼装的固定说明，不是用户/模型对话；
164:             // 混进来会让每次搜索都命中同一段模板，把真正的会话内容压下去。
165:             RolloutItem::SessionMeta { .. }
166:             | RolloutItem::SubagentRef { .. }
167:             | RolloutItem::SandboxMode { .. }
168:             | RolloutItem::AbortNote { .. }
169:             | RolloutItem::TurnEnd { .. }
170:             | RolloutItem::SystemPrompt { .. } => {}
171:         }
172:     }
173:     documents
174: }
175: 
176: /// 会被压缩锚点取代的档案下标集合（`surface = shadowed`）。
177: ///
178: /// 序号口径必须与 `rollout::resume` / `lib.rs::project_entries` 完全一致：
179: /// 只数进入历史序列的条目（消息、调用、**工具输出**、图片），锚点用一条摘要
180: /// 顶掉 `[range_start, range_end)`——所以这里用一个哨兵值占住摘要那个槽位，
181: /// 否则后一个锚点的区间会整体错位一格。
182: fn shadowed_indices(_items: &[RolloutItem]) -> HashSet<usize> {
183:     // 回归：surface 判定被删掉，所有文档一律当 current。
184:     HashSet::new()
185: }
186: 
187: /// 是否进入历史序列（`rollout::resume` 的重放口径）。`TurnEnd` 等审计记录不在其中。
188: fn is_history_item(item: &RolloutItem) -> bool {
189:     matches!(
190:         item,
191:         RolloutItem::ResponseItem {
192:             item: HistoryItem::Message { .. }
193:                 | HistoryItem::FunctionCall { .. }
194:                 | HistoryItem::FunctionCallOutput { .. }
195:                 | HistoryItem::ImageMessage { .. },
196:             ..
197:         }
198:     )
199: }
200: 
201: fn role_doc_type(role: Role) -> &'static str {
202:     match role {
203:         Role::User => "user/message",
204:         Role::Assistant => "assistant/message",
205:         Role::System => "system/message",
206:     }
207: }
208: 
209: /// 上游 `extraction.ts` 的 `joinText`：逐段 trim、丢空段、换行拼接。
210: fn join_text(parts: &[&str]) -> String {
211:     parts
212:         .iter()
213:         .map(|part| part.trim())
214:         .filter(|part| !part.is_empty())
215:         .collect::<Vec<_>>()
216:         .join("\n")
217: }

