43: /// 派生索引文件名（落在 `<data_root>/cache/`，可安全清空重建）。
44: pub const INDEX_FILE: &str = "session-search.db";
45: /// 宿主固定的结果上限：与 DSH `SESSION_SEARCH_RESULT_LIMIT = 20` 同源。
46: /// 命中会话数超过它时 `hasMore=true`，语义是「请收窄查询」，不是分页游标。
47: pub const RESULT_LIMIT: u32 = 20;
48: /// 最大 snippet 长度（Unicode 码点）：与上游 `snippetChars = 240` 同源。
49: pub const SNIPPET_CHARS: usize = 240;
