51: /// 类型化搜索错误：前端按 `code` 分派 wire 错误，不靠匹配中文措辞。
52: /// 形状与 `rollout::RenameError` / `lib::WorkspaceOpError` 一致（04 §1.3 风格）。
53: #[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
54: #[serde(tag = "code", content = "message", rename_all = "kebab-case")]
55: pub enum SearchError {
56:     /// 查询含 NUL（空/纯空白不是错误，按上游回空表）。
57:     InvalidQuery(String),
58:     /// 查询超过 wire 上限（500 UTF-16 code units）。
59:     QueryTooLong(String),
60:     /// 索引打不开、schema 校验失败、对账或查询失败。
61:     IndexFailed(String),
62:     /// rollout 档案读失败（严格口径，不返回空表冒充"没搜到"）。
63:     ArchiveReadFailed(String),
64: }
