80: /// `session.search` wire 的返回页：`hasMore` = 命中会话数超过 `RESULT_LIMIT`，
81: /// 只驱动 UI 一行「结果较多，请收窄查询」提示，没有续页请求。
82: #[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
83: #[serde(rename_all = "camelCase")]
84: pub struct SearchPage {
85:     pub items: Vec<SearchHit>,
86:     pub has_more: bool,
87:     /// 本次搜索**跳过**的会话档案数（读不回来：被占用、权限、半截文件）。
88:     ///
89:     /// 局部失败不该升级成全局失败：坏的是某一个会话的档案，不能罚到所有会话头上。
90:     /// 但少给了就必须说出来——`skipped_sessions > 0` 表示「这次结果不完整」，
91:     /// 与「标注缺失好过标注错位」同一条原则：缺失要说出来，不能悄悄少给。
92:     pub skipped_sessions: u32,
93: }
94: 
95: /// 索引失败后的冷却时长：这段时间内不再尝试打开索引文件。
96: ///
97: /// 行为对齐 codex `codex-mcp/src/client_tool_catalog.rs:175-232`：失败后记下
98: /// `retry_not_before`，冷却期内的再次请求直接返回，不再重新抓取（它取 5 秒，
99: /// 那里是进程内的内存目录；我们面对的是磁盘/权限故障，取 30 秒）。
100: const INDEX_FAILURE_COOLDOWN: Duration = Duration::from_secs(30);
101: 
102: /// 一条失败记忆：哪条索引、什么原因、什么时候、当时的文件状态。
103: struct IndexFailure {
104:     path: PathBuf,
105:     message: String,
106:     at: Instant,
107:     /// 失败时索引文件的指纹（大小 + 修改时间）。文件被换掉/删掉/重建后指纹变化，
108:     /// 说明"现场被改过了"，就不该继续用旧失败拦着——用户清磁盘、换文件后
109:     /// 不必等满冷却或点重试。
110:     stamp: Option<(u64, Option<std::time::SystemTime>)>,
111: }
112: 
113: /// 失败记忆表：按索引路径各记一条。进程内通常只有一条（一个 `data_root`），
114: /// 但测试与多根场景会并行，单槽会被互相覆盖，所以按路径分开存。
115: static INDEX_FAILURES: Mutex<Vec<IndexFailure>> = Mutex::new(Vec::new());
116: 
117: /// 最多保留几条失败记忆（防止无界增长；正常只有一个 `data_root`）。
118: const FAILURE_SLOTS: usize = 8;
119: 
120: // 测试专用：打开索引的尝试次数。用于证明冷却期真的没有再去碰文件，
121: // 而不是"又撞了一次墙但恰好返回了同一条错误"。
122: // 用线程局部量：测试并行跑，全局计数会把别的用例的尝试次数算进来。
123: #[cfg(test)]
124: thread_local! {
125:     static OPEN_ATTEMPTS: std::cell::Cell<usize> = const { std::cell::Cell::new(0) };
126: }
127: 
128: #[cfg(test)]
129: pub(crate) fn open_attempts() -> usize {
130:     OPEN_ATTEMPTS.with(std::cell::Cell::get)
131: }
132: 
133: fn failure_slot() -> std::sync::MutexGuard<'static, Vec<IndexFailure>> {
134:     // 失败记忆只是 hint，锁中毒不该让搜索整体不可用。
135:     INDEX_FAILURES.lock().unwrap_or_else(|poisoned| poisoned.into_inner())
136: }
137: 
138: /// 索引文件的当前指纹：不存在时为 `None`。
139: fn index_stamp(index_path: &Path) -> Option<(u64, Option<std::time::SystemTime>)> {
140:     let meta = fs::metadata(index_path).ok()?;
141:     Some((meta.len(), meta.modified().ok()))
142: }
143: 
144: /// 冷却期内：返回上次的同一条错误（同一个 code、同一个原因），不再触碰索引文件。
145: fn cooldown_message(index_path: &Path) -> Option<String> {
146:     let guard = failure_slot();
147:     let failure = guard.iter().find(|failure| failure.path == index_path)?;
148:     if failure.at.elapsed() >= INDEX_FAILURE_COOLDOWN {
149:         return None;
150:     }
151:     // 现场被改过（文件被删/被换/被重建）就不再拦：那可能正是用户在自救。
152:     if failure.stamp != index_stamp(index_path) {
153:         return None;
154:     }
155:     Some(format!(
156:         "{}（索引仍不可用，{} 秒内不再重复尝试，可手动重试）",
157:         failure.message,
158:         INDEX_FAILURE_COOLDOWN.as_secs()
159:     ))
160: }
161: 
162: fn remember_failure(index_path: &Path, message: &str) {
163:     let mut guard = failure_slot();
164:     let failure = IndexFailure {
165:         path: index_path.to_path_buf(),
166:         message: message.to_string(),
167:         at: Instant::now(),
168:         stamp: index_stamp(index_path),
169:     };
170:     match guard.iter_mut().find(|slot| slot.path == index_path) {
171:         Some(slot) => *slot = failure,
172:         None => {
173:             if guard.len() == FAILURE_SLOTS {
174:                 // 淘汰最老的一条：记忆只是 hint，丢掉不影响正确性。
175:                 guard.remove(0);
176:             }
177:             guard.push(failure);
178:         }
179:     }
180: }
181: 
182: /// 一次成功搜索只清掉**自己这条路径**的失败记忆，不影响别的索引路径。
183: fn clear_failure(index_path: &Path) {
184:     failure_slot().retain(|failure| failure.path != index_path);
185: }
186: 
187: /// 清掉全部失败记忆：重试入口调用它，下一次搜索重新尝试打开索引。
188: pub fn retry_index_now() {
189:     failure_slot().clear();
190: }
191: 
192: /// 一次搜索的完整入口（被 `lib.rs::search_sessions` 命令壳调用）。
193: ///
194: /// `data_root` 来自 `AppState::data_root()`（§9.3 目录解析），索引路径复用
195: /// `config::CACHE_DIR`，不新造一套目录体系。空/纯空白查询按上游语义直接回空表，
196: /// 连 SQLite 都不打开（首搜惰性更彻底）。
197: pub fn search(data_root: &Path, raw_query: &str) -> Result<SearchPage, SearchError> {
198:     if raw_query.trim().is_empty() {
199:         return Ok(SearchPage { items: Vec::new(), has_more: false, skipped_sessions: 0 });
200:     }
201:     let normalized = query::normalize_query(raw_query)?;
202: 
203:     // first-search 惰性打开：启动阶段完全不碰 SQLite。
204:     let index_path = data_root.join(config::CACHE_DIR).join(INDEX_FILE);
205:     if let Some(message) = cooldown_message(&index_path) {
206:         return Err(SearchError::IndexFailed(message));
207:     }
208: 
209:     let rollouts = data_root.join(rollout::ROLLOUT_DIR);
210:     let result = search_with_index(&index_path, &rollouts, &normalized.expression);
211:     match &result {
212:         Ok(_) => clear_failure(&index_path),
213:         // 只有索引侧的失败才进冷却；档案侧的局部失败已经在 reconcile 里降级了。
214:         Err(SearchError::IndexFailed(message)) => remember_failure(&index_path, message),
215:         Err(_) => {}
216:     }
217:     result
218: }
219: 
220: fn search_with_index(
221:     index_path: &Path,
222:     rollouts: &Path,
223:     expression: &str,
224: ) -> Result<SearchPage, SearchError> {
225:     #[cfg(test)]
226:     OPEN_ATTEMPTS.with(|attempts| attempts.set(attempts.get() + 1));
227:     let mut conn = schema::open_index(index_path)?;
228: 
229:     let tx = conn
230:         .transaction()
231:         .map_err(|e| SearchError::IndexFailed(format!("开启索引对账事务失败: {e}")))?;
232:     let skipped_sessions = reconcile(&tx, rollouts)?;
233:     // 多取一条判断「是否超过上限」；SQL 内部已按 session_id 分组只留最强命中。
234:     let rows = run_query(&tx, expression, RESULT_LIMIT + 1)?;
235:     tx.commit()
236:         .map_err(|e| SearchError::IndexFailed(format!("提交索引对账失败: {e}")))?;
237: 
238:     let has_more = rows.len() > RESULT_LIMIT as usize;
239:     let items: Vec<SearchHit> = rows
240:         .into_iter()
241:         .take(RESULT_LIMIT as usize)
242:         .map(|row| {
243:             let snippet = query::make_snippet(&row.marked_text, SNIPPET_CHARS);
244:             // 回归：surface 标注被去掉了，命中一律当 current。
245:             SearchHit { session_id: row.session_id, snippet }
246:         })
247:         .collect();
248:     Ok(SearchPage {
249:         items,
250:         has_more,
251:         // 截到 wire 的类型范围：它的唯一用途是「这次结果不完整」的数量提示。
252:         skipped_sessions: u32::try_from(skipped_sessions).unwrap_or(u32::MAX),
253:     })
254: }
255: 
256: /// 一行查询结果的中间形状（只保留生成 snippet 所需的字段）。
257: struct QueryRow {
258:     session_id: String,
259:     marked_text: String,
260:     /// `current` / `shadowed`：这段原文是否还在模型当前的历史里。
261:     surface: String,
262: }
263: 
264: /// 执行 UNION + 排名 + 限量查询。排名按上游口径：
265: /// 命中 span 多者优先 → 文档短者优先 → 时间 → session id → seq 兜底；不伪造数值分数。
266: fn run_query(
267:     tx: &Transaction<'_>,
268:     expression: &str,
269:     limit: u32,
270: ) -> Result<Vec<QueryRow>, SearchError> {
271:     let mut stmt = tx
272:         .prepare(query::SEARCH_SQL)
273:         .map_err(|e| SearchError::IndexFailed(format!("准备搜索语句失败: {e}")))?;
274:     let marker_bytes = query::FTS_HIGHLIGHT_START.len() as i64;
275:     let rows = stmt
276:         .query_map(
277:             params![
278:                 query::FTS_HIGHLIGHT_START,
279:                 query::FTS_HIGHLIGHT_END,
280:                 expression,
281:                 query::FTS_HIGHLIGHT_START,
282:                 query::FTS_HIGHLIGHT_END,
283:                 expression,
284:                 query::FTS_HIGHLIGHT_START,
285:                 marker_bytes,
286:                 i64::from(limit),
287:             ],
288:             |row| {
289:                 Ok(QueryRow {
290:                     session_id: row.get::<_, String>("session_id")?,
291:                     marked_text: row.get::<_, String>("marked_text")?,
292:                     surface: row.get::<_, String>("surface")?,
293:                 })
294:             },
295:         )
296:         .map_err(|e| SearchError::IndexFailed(format!("搜索执行失败: {e}")))?;
297:     let mut out = Vec::new();
298:     for row in rows {
299:         out.push(row.map_err(|e| SearchError::IndexFailed(format!("读取搜索结果失败: {e}")))?);
300:     }
301:     Ok(out)
302: }
303: 
304: /// 磁盘档案的 revision：内容哈希 + 字节数。内容变（运行中追加）必然变；
305: /// mtime 不作为判据（Windows 上的时间戳粒度与跨机器复制都不可靠）。
306: fn revision_of(bytes: &[u8]) -> String {
307:     let mut hasher = DefaultHasher::new();
308:     bytes.hash(&mut hasher);
309:     format!("{:016x}:{}", hasher.finish(), bytes.len())
310: }
311: 
312: /// 一次串行对账（上游 `_reconcile` 的 SHANIU 等价）：
313: /// 列出磁盘快照 → 与 base 的逐会话 revision 比对 → 只读新增/变化档案 → 抽语义文档
314: /// → 在一个事务里把变化会话写入 TEMP live 表（shadow base）并同步更新 base → bump generation。
315: ///
316: /// 返回本次**读不回来而跳过**的档案数；`> 0` 表示这次结果不完整，必须交给调用方。
317: fn reconcile(tx: &Transaction<'_>, rollouts: &Path) -> Result<usize, SearchError> {
318:     tx.execute("DELETE FROM temp.live_docs", [])
319:         .and_then(|_| tx.execute("DELETE FROM temp.live_sessions", []))
320:         .map_err(|e| SearchError::IndexFailed(format!("清空 live 观察表失败: {e}")))?;
321: 
322:     let indexed = read_indexed_revisions(tx)?;
323:     let observed = observe_archives(rollouts)?;
324:     let skipped = observed.unreadable.len();
325:     let unreadable: HashSet<&String> = observed.unreadable.iter().collect();
326: 
327:     let mut changed: Vec<ObservedSession> = Vec::new();
328:     for session in observed.sessions.values() {
329:         match indexed.get(&session.id) {
330:             Some(revision) if revision == &session.revision => {}
331:             _ => changed.push(session.clone()),
332:         }
333:     }
334:     // 读不回来的档案不等于「已删除」：删掉它已索引的行，等于因为一次读失败
335:     // 把历史内容从搜索里抹掉（codex `client_tool_catalog.rs:9` 对同类情况的口径是
336:     // 保留 last good catalog）。保留旧行 + 计入 skipped，宁可给稍旧的命中。
337:     let deleted: Vec<String> = indexed
338:         .keys()
339:         .filter(|id| !observed.sessions.contains_key(*id) && !unreadable.contains(*id))
340:         .cloned()
341:         .collect();
342:     let has_writes = !changed.is_empty() || !deleted.is_empty();
343:     if !has_writes {
344:         return Ok(skipped);
345:     }
346: 
347:     let generation = schema::read_generation(tx)?.parse::<i64>().unwrap_or(0) + 1;
348:     for id in &deleted {
349:         tx.execute("DELETE FROM persisted_docs WHERE session_id = ?1", params![id])
350:             .map_err(|e| SearchError::IndexFailed(format!("删除失效索引行失败: {e}")))?;
351:         tx.execute("DELETE FROM persisted_sessions WHERE id = ?1", params![id])
352:             .map_err(|e| SearchError::IndexFailed(format!("删除失效会话登记失败: {e}")))?;
353:     }
354:     for session in &changed {
355:         replace_session(tx, session, generation)?;
356:     }
357:     tx.execute(
358:         "UPDATE search_state SET global_generation = ?1 WHERE singleton = 1",
359:         params![generation],
360:     )
361:     .map_err(|e| SearchError::IndexFailed(format!("更新索引世代失败: {e}")))?;
362:     Ok(skipped)
363: }
364: 
365: /// 一个磁盘上观察到的会话（本次搜索的当前态）。
366: #[derive(Debug, Clone, PartialEq, Eq)]
367: struct ObservedSession {
368:     id: String,
369:     revision: String,
370:     created_at: u64,
371:     documents: Vec<documents::SearchDoc>,
372: }
373: 
374: /// 一次磁盘观察的结果：读得回来的会话，以及读不回来的档案 id。
375: ///
376: /// 「单个档案读不回来」是局部失败，不是全局失败：坏的是某一个会话，不该罚到
377: /// 所有会话头上（DSH `session-query/src/corpus.ts:30-33,139-176` 把批次结果
378: /// 定义成逐会话 `fulfilled | rejected`，只有取消才整体中止）。
379: struct ObservedArchives {
380:     sessions: BTreeMap<String, ObservedSession>,
381:     /// 读不回来的档案 id：对账时不能被当成「已删除」，并且要计入 `skipped_sessions`。
382:     unreadable: Vec<String>,
383: }
384: 
385: /// 扫描 rollout 目录，对每个 `.jsonl` 算 revision；变化的会话顺带抽出语义文档。
386: /// 只读：整个函数对 rollouts 目录没有任何写操作（AGENTS §3 + SH-113 验收红线）。
387: fn observe_archives(rollouts: &Path) -> Result<ObservedArchives, SearchError> {
388:     let mut sessions = BTreeMap::new();
389:     let mut unreadable = Vec::new();
390:     let entries = match fs::read_dir(rollouts) {
391:         Ok(entries) => entries,
392:         // 目录不存在 = 首次运行的正常状态（与 rollout::list 同口径），不是错误。
393:         Err(e) if e.kind() == std::io::ErrorKind::NotFound => {
394:             return Ok(ObservedArchives { sessions, unreadable })
395:         }
396:         Err(e) => {
397:             return Err(SearchError::ArchiveReadFailed(format!(
398:                 "读取会话档案目录失败 {}: {e}",
399:                 rollouts.display()
400:             )))
401:         }
402:     };
403:     for entry in entries {
404:         let entry = entry.map_err(|e| {
405:             SearchError::ArchiveReadFailed(format!("枚举会话档案失败: {e}"))
406:         })?;
407:         let path: PathBuf = entry.path();
408:         if path.extension().and_then(|ext| ext.to_str()) != Some("jsonl") {
409:             continue;
410:         }
411:         let Some(id) = path.file_stem().map(|s| s.to_string_lossy().into_owned()) else {
412:             continue;
413:         };
414:         // 单个档案读不回来（被占用、权限、写了一半）：跳过它继续索引其余的，
415:         // 并把它记进 `unreadable`。跳过 ≠ 假装它不存在——调用方必须把数量交出去。
416:         let bytes = match fs::read(&path) {
417:             Ok(bytes) => bytes,
418:             Err(e) => {
419:                 tracing::warn!(session = %id, path = %path.display(), "会话档案读不回来，本次搜索跳过: {e}");
420:                 unreadable.push(id);
421:                 continue;
422:             }
423:         };
424:         let revision = revision_of(&bytes);
425:         let archive = match rollout::read(&path) {
426:             Ok(archive) => archive,
427:             Err(e) => {
428:                 tracing::warn!(session = %id, path = %path.display(), "会话档案解析失败，本次搜索跳过: {e}");
429:                 unreadable.push(id);
430:                 continue;
431:             }
432:         };
433:         let created_at = match &archive.meta {
434:             RolloutItem::SessionMeta { created_at, .. } => *created_at,
435:             _ => 0,
436:         };
437:         let documents = documents::build_documents(&archive.items, created_at);
438:         sessions.insert(
439:             id.clone(),
440:             ObservedSession { id, revision, created_at, documents },
441:         );
442:     }
443:     if !unreadable.is_empty() {
444:         // 计数给用户（`skipped_sessions` 只说「这次不完整」），id 给排障：
445:         // 只看到「3 个会话无法检索」时无从下手，日志里必须能点名具体是哪几个档案。
446:         // 落点是 `shaniu.log`（config.rs `LOG_FILE_PREFIX`），逐条 warn 之外再给一条
447:         // 汇总，grep 一次就能拿到全量列表。
448:         tracing::warn!(
449:             count = unreadable.len(),
450:             sessions = %unreadable.join(","),
451:             "本次搜索跳过了读不回来的会话档案"
452:         );
453:     }
454:     Ok(ObservedArchives { sessions, unreadable })
455: }
456: 
457: fn read_indexed_revisions(
458:     tx: &Transaction<'_>,
459: ) -> Result<HashMap<String, String>, SearchError> {
460:     let mut stmt = tx
461:         .prepare("SELECT id, revision FROM persisted_sessions")
462:         .map_err(|e| SearchError::IndexFailed(format!("读取已索引会话失败: {e}")))?;
463:     let rows = stmt
464:         .query_map([], |row| {
465:             Ok((row.get::<_, String>(0)?, row.get::<_, String>(1)?))
466:         })
467:         .map_err(|e| SearchError::IndexFailed(format!("读取已索引会话失败: {e}")))?;
468:     let mut out = HashMap::new();
469:     for row in rows {
470:         let (id, revision) =
471:             row.map_err(|e| SearchError::IndexFailed(format!("读取已索引会话失败: {e}")))?;
472:         out.insert(id, revision);
473:     }
474:     Ok(out)
475: }
476: 
477: /// 把一个变化会话同时写进 TEMP live 表（本次观察的当前态，shadow base）与 persisted base
478: /// （跨重启保留）。SQL 的 `NOT EXISTS` 保证同一会话只从 live 表出结果，不会重复计分。
479: fn replace_session(
480:     tx: &Transaction<'_>,
481:     session: &ObservedSession,
482:     generation: i64,
483: ) -> Result<(), SearchError> {
484:     tx.execute("DELETE FROM persisted_docs WHERE session_id = ?1", params![session.id])
485:         .map_err(|e| SearchError::IndexFailed(format!("清理旧索引行失败: {e}")))?;
486:     tx.execute(
487:         "INSERT OR REPLACE INTO persisted_sessions (id, revision, generation) VALUES (?1, ?2, ?3)",
488:         params![session.id, session.revision, generation],
489:     )
490:     .map_err(|e| SearchError::IndexFailed(format!("登记会话索引失败: {e}")))?;
491:     tx.execute(
492:         "INSERT OR REPLACE INTO temp.live_sessions (id, fingerprint, persisted, generation) VALUES (?1, ?2, 1, ?3)",
493:         params![session.id, session.revision, generation],
494:     )
495:     .map_err(|e| SearchError::IndexFailed(format!("登记 live 观察失败: {e}")))?;
496: 
497:     for doc in &session.documents {
498:         let values = params![
499:             doc.text,
500:             session.id,
501:             doc.seq,
502:             doc.doc_type,
503:             doc.time,
504:             "current",
505:             doc.codepoint_length,
506:         ];
507:         tx.execute(
508:             "INSERT INTO persisted_docs (text, session_id, seq, type, time, surface, codepoint_length) VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7)",
509:             values,
510:         )
511:         .map_err(|e| SearchError::IndexFailed(format!("写入持久化索引行失败: {e}")))?;
512:         tx.execute(
513:             "INSERT INTO temp.live_docs (text, session_id, seq, type, time, surface, codepoint_length) VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7)",
514:             values,
515:         )
