1: //! 请求归一化、参数化谓词与 snippet（SH-113）。
2: //!
3: //! 上游 `session-query-sqlite/src/query.ts` 的 Rust 等价：`normalizeQuery` 的空白归一
4: //! 与 NUL/长度校验、`quoteFtsData` 的 literal phrase 转义、`makeSnippet` 的按码点截断。
5: //! 另含一处 SHANIU 特有补充：CJK 单字化（见 `fts_text`）——SQLite FTS5 `unicode61`
6: //! 默认把连续 CJK 字符合成**一个** token，单字查询无法命中；在文档入库与查询归一化
7: //! 两侧对称插入零宽分隔，让每个汉字独立成 token，同时连续中文短语以 phrase 命中。
8: //! tokenizer 仍是 `unicode61`，查询仍是单个 literal phrase，语法字符仍是数据。
9: //!
10: //! 命令面按 vendored wire 收敛为 `query-only`：没有 cursor/limit 入参，故这里不保留
11: //! 任何分页游标能力（`session.search` 前端永远传不进来，留着即死接口）。
12: 
13: use crate::session_query::SearchError;
14: 
15: /// FTS5 `highlight()` 的碰撞-free 起止标记（上游 `FTS_HIGHLIGHT_START/END`）。
16: pub const FTS_HIGHLIGHT_START: &str = "\u{FDD0}";
17: pub const FTS_HIGHLIGHT_END: &str = "\u{FDD1}";
18: const HL_START_CHAR: char = '\u{FDD0}';
19: const HL_END_CHAR: char = '\u{FDD1}';
20: 
21: /// CJK 单字化用的零宽分隔符：unicode61 把它当分隔符（Cf 不在默认 categories 里），
22: /// 视觉上不可见，snippet 生成时剥掉即可还原原文观感。
23: const ZWSP: char = '\u{200B}';
24: 
25: /// 与 DSH wire `SEARCH_QUERY_MAX_CODE_UNITS` 同源（WorkspaceBrowser.tsx:53）。
26: pub const MAX_QUERY_UTF16: usize = 500;
27: 
28: /// 归一化后的查询：`expression` 是唯一送往 MATCH 的字符串；`data` 供测试对照分词口径。
29: #[derive(Debug, Clone, PartialEq, Eq)]
30: pub struct NormalizedQuery {
31:     pub data: String,
32:     pub expression: String,
33: }
34: 
35: /// 校验并规范化一次搜索请求：空白归一、拒绝 NUL 与超长输入。
36: /// 生产路径上空/纯空白由 `session_query::search` 短路成空表（上游语义），这里的
37: /// 空串分支只是防止误调时构造出非法空 phrase 的内部防御。
38: pub fn normalize_query(raw: &str) -> Result<NormalizedQuery, SearchError> {
39:     let normalized = raw.split_whitespace().collect::<Vec<_>>().join(" ");
40:     if normalized.is_empty() {
41:         return Err(SearchError::InvalidQuery(
42:             "搜索词不能为空（首尾空白已忽略）".to_string(),
43:         ));
44:     }
45:     if normalized.contains('\0') {
46:         return Err(SearchError::InvalidQuery("搜索词不能含 NUL 字符".to_string()));
47:     }
48:     if normalized.encode_utf16().count() > MAX_QUERY_UTF16 {
49:         return Err(SearchError::QueryTooLong(format!(
50:             "搜索词超过 {MAX_QUERY_UTF16} 个 UTF-16 码元，请缩短后再搜"
51:         )));
52:     }
53:     let data = fts_text(&normalized);
54:     let expression = quote_fts_data(&data);
55:     Ok(NormalizedQuery { data, expression })
56: }
57: 
58: /// 把调用方文本 quoted 成**单个** FTS5 phrase。引号翻倍转义，其余字符
59: /// （`OR` / `NEAR` / `*` / `-` / `(` / `:` …）在 phrase 内一律是数据，
60: /// 绝不拼成可执行 MATCH 表达式（防注入 + 防语法报错）。
61: pub fn quote_fts_data(query: &str) -> String {
62:     format!("\"{}\"", query.replace('"', "\"\""))
63: }
64: 
65: /// 归一化文本使其进入 FTS5：先脱敏保留标记，再做 CJK 单字化。
66: ///
67: /// 对文档与查询**对称**应用，保证 phrase 的 token 序列与索引一致。
68: pub fn fts_text(text: &str) -> String {
69:     let mut out = String::with_capacity(text.len() + text.len() / 2);
70:     // 开头不需要前导分隔符；记录上一位是否已是分隔符，避免连续插入两个。
71:     let mut prev_separator = true;
72:     for original in text.chars() {
73:         let ch = match original {
74:             '\0' | HL_START_CHAR | HL_END_CHAR => '\u{FFFD}',
75:             other => other,
76:         };
77:         if ch == ZWSP {
78:             out.push(ZWSP);
79:             prev_separator = true;
80:             continue;
81:         }
82:         if is_cjk_char(ch) {
83:             if !prev_separator {
84:                 out.push(ZWSP);
85:             }
86:             out.push(ch);
87:             out.push(ZWSP);
88:             prev_separator = true;
89:         } else {
90:             out.push(ch);
91:             prev_separator = false;
92:         }
93:     }
94:     out.trim_matches(ZWSP).to_string()
95: }
96: 
97: /// CJK 表意文字、日文假名、韩文音节：这些文字在 unicode61 下会连续成 token，
98: /// 需要逐字切开才能让单字查询命中（SH-113 验收「中文单字成词」）。
99: fn is_cjk_char(ch: char) -> bool {
100:     let code = ch as u32;
101:     (0x3400..=0x4DBF).contains(&code)        // 扩展 A
102:         || (0x4E00..=0x9FFF).contains(&code) // 基本区
103:         || (0xF900..=0xFAFF).contains(&code) // 兼容表意文字
104:         || (0x20000..=0x2FA1F).contains(&code) // 扩展 B–F / 兼容扩展
105:         || (0x3040..=0x30FF).contains(&code) // 平假名 / 片假名
106:         || (0xAC00..=0xD7AF).contains(&code) // 韩文音节
107: }
108: 
109: /// 从 `highlight()` 的标记文本生成有界纯文本片段（上游 `makeSnippet` 逐行等价）。
110: /// 按 Unicode 码点截断、以首个命中位置居中、空白归一、剥掉零宽分隔符与标记。
111: pub fn make_snippet(marked: &str, max_chars: usize) -> String {
112:     let (clean, match_start) = normalize_marked_text(marked);
113:     let characters: Vec<char> = clean.chars().collect();
114:     if characters.len() <= max_chars {
115:         return clean;
116:     }
117:     if max_chars == 1 {
118:         return "…".to_string();
119:     }
120:     let matched_index = match_start.min(characters.len() - 1);
121:     let mut start = matched_index.saturating_sub(max_chars / 3);
122:     let prefix = if start > 0 { "…" } else { "" };
123:     let mut suffix = "…";
124:     let mut content_length = max_chars - prefix.chars().count() - suffix.chars().count();
125:     if content_length < 1 {
126:         start = matched_index;
127:         suffix = "";
128:         content_length = max_chars - prefix.chars().count();
129:     } else if matched_index >= start + content_length {
130:         start = matched_index + 1 - content_length;
131:     }
132:     let mut end = (start + content_length).min(characters.len());
133:     if end == characters.len() {
134:         suffix = "";
135:         content_length = max_chars - prefix.chars().count();
136:         start = end.saturating_sub(content_length);
137:     }
138:     end = (start + content_length).min(characters.len());
139:     let body: String = characters[start..end].iter().collect();
140:     format!("{prefix}{body}{suffix}")
141: }
142: 
143: /// 去掉 highlight 标记、空白归一为单空格、剥掉零宽分隔符；返回首个命中的字符位置。
144: fn normalize_marked_text(marked: &str) -> (String, usize) {
145:     let mut characters: Vec<char> = Vec::new();
146:     let mut match_start: Option<usize> = None;
147:     for ch in marked.chars() {
148:         if ch == HL_START_CHAR {
149:             if match_start.is_none() {
150:                 match_start = Some(characters.len());
151:             }
152:             continue;
153:         }
154:         if ch == HL_END_CHAR || ch == ZWSP {
155:             continue;
156:         }
157:         if ch.is_whitespace() {
158:             if !characters.is_empty() && characters.last() != Some(&' ') {
159:                 characters.push(' ');
160:             }
161:         } else {
162:             characters.push(ch);
163:         }
164:     }
165:     if characters.last() == Some(&' ') {
166:         characters.pop();
167:     }
168:     (characters.iter().collect(), match_start.unwrap_or(0))
169: }
170: 
171: /// 跨会话搜索：persisted base + connection-local live TEMP 表 UNION，按每会话最强命中
172: /// 分组（`event_rank = 1` 保证一个 sessionId 只出一条），再按「命中 span 多 → 文档短 →
173: /// 时间 → session id → seq」排名并限量。没有 OFFSET：wire 没有续页请求。
174: ///
175: /// 参数顺序固定（见 `session_query::run_query`）：
176: /// `[HL_START, HL_END, expression, HL_START, HL_END, expression, HL_START, marker_bytes, limit]`。
177: pub const SEARCH_SQL: &str = "
178: WITH candidates AS (
179:   SELECT
180:     persisted_docs.session_id AS session_id,
181:     0 AS live,
182:     1 AS persisted,
183:     CAST(persisted_docs.seq AS INTEGER) AS seq,
184:     persisted_docs.type AS type,
185:     CAST(persisted_docs.time AS INTEGER) AS time,
186:     'current' AS surface,
187:     highlight(persisted_docs, 0, ?1, ?2) AS marked_text,
188:     CAST(persisted_docs.codepoint_length AS INTEGER) AS document_length
189:   FROM persisted_docs
190:   JOIN persisted_sessions ON persisted_sessions.id = persisted_docs.session_id
191:   WHERE persisted_docs MATCH ?3
192:     AND NOT EXISTS (SELECT 1 FROM temp.live_sessions AS ls WHERE ls.id = persisted_docs.session_id)
193:   UNION ALL
194:   SELECT
195:     live_docs.session_id AS session_id,
196:     1 AS live,
197:     live_sessions.persisted AS persisted,
198:     CAST(live_docs.seq AS INTEGER) AS seq,
199:     live_docs.type AS type,
200:     CAST(live_docs.time AS INTEGER) AS time,
201:     'current' AS surface,
202:     highlight(live_docs, 0, ?4, ?5) AS marked_text,
203:     CAST(live_docs.codepoint_length AS INTEGER) AS document_length
204:   FROM temp.live_docs AS live_docs
205:   JOIN temp.live_sessions AS live_sessions ON live_sessions.id = live_docs.session_id
206:   WHERE live_docs MATCH ?6
207: ), matched AS (
208:   SELECT *,
209:     (
210:       length(CAST(marked_text AS BLOB))
211:       - length(CAST(replace(marked_text, ?7, '') AS BLOB))
212:     ) / ?8 AS match_count
213:   FROM candidates
214: ), ranked AS (
215:   SELECT *, ROW_NUMBER() OVER (
216:     PARTITION BY session_id
217:     ORDER BY match_count DESC, document_length ASC, time DESC, seq DESC
218:   ) AS event_rank
219:   FROM matched
220: )
221: SELECT * FROM ranked
222: WHERE event_rank = 1
223: ORDER BY match_count DESC, document_length ASC, time DESC, session_id ASC, seq DESC
224: LIMIT ?9
225: ";

