210: /// 损坏件保留 **第一份 + 最近两份**（总数上限）。
211: ///
212: /// 不采用单纯「最近 N 份」：轮转删除先删最早的，而最早那份恰恰是**第一次损坏的
213: /// 原始现场**——后面几份可能只是同一个 bug 在重复发生，只留最近的等于把唯一干净
214: /// 样本丢掉，等想查的时候已经没有可对照的基线。
215: ///
216: /// 自创（参考源里都没有自动上限）：DSH `storage-domain` 的 backup-and-skip 只隔离不清理；
217: /// ZCode `settingService.ts` 的 `.corrupt-<ts>` 交给「存储清理」界面由用户删；
218: /// codex 无对应机制。清理是尽力而为，失败不影响重建。
219: pub(crate) const QUARANTINE_KEEP: usize = 3;
220: 
221: /// 把损坏的索引文件改名保留（含 WAL/SHM/journal 附属），再让调用方新建。
222: /// 目标是"不误删"，所以 rename 失败一律报错而不是强行覆盖。
223: fn quarantine(path: &Path) -> Result<(), SearchError> {
224:     let stamp = SystemTime::now()
225:         .duration_since(UNIX_EPOCH)
226:         .map(|d| d.as_millis())
227:         .unwrap_or_default();
228:     let name = path
229:         .file_name()
230:         .map(|n| n.to_string_lossy().into_owned())
231:         .unwrap_or_else(|| "session-search.db".to_string());
232:     let mut counter = 0u32;
233:     let target: PathBuf;
234:     loop {
235:         let suffix = if counter == 0 {
236:             format!("{name}.corrupt-{}-{stamp}", std::process::id())
237:         } else {
238:             format!("{name}.corrupt-{}-{stamp}-{counter}", std::process::id())
239:         };
240:         let candidate = path.with_file_name(suffix);
241:         if !candidate.exists() {
242:             target = candidate;
243:             break;
244:         }
245:         counter += 1;
246:     }
247:     fs::rename(path, &target).map_err(|e| {
248:         SearchError::IndexFailed(format!(
249:             "损坏索引改名保留失败 {} → {}: {e}（不删除原文件）",
250:             path.display(),
251:             target.display()
252:         ))
253:     })?;
254:     // 附属文件尽力一并移走；残留不阻断重建，但绝不主动删除。
255:     for suffix in ["-wal", "-shm", "-journal"] {
256:         let mut side = path.as_os_str().to_os_string();
257:         side.push(suffix);
258:         let side = PathBuf::from(side);
259:         if side.exists() {
260:             let mut side_target = target.as_os_str().to_os_string();
261:             side_target.push(suffix);
262:             let _ = fs::rename(&side, PathBuf::from(side_target));
263:         }
264:     }
265:     prune_quarantined(&target, &name);
266:     Ok(())
267: }
268: 
269: /// 隔离件文件名里的毫秒时间戳：`{name}.corrupt-{pid}-{stamp}[-{counter}]`。
270: ///
271: /// 不能用 mtime 排序：`rename` 会保留原文件的修改时间，一份「今天刚改名」的隔离件
272: /// 可能带着几个月前的 mtime —— 按 mtime 会把第一次损坏的现场误判成最新的，
273: /// 恰好把要保的那份删掉。文件名里的 stamp 才是隔离发生的真实先后。
274: fn quarantine_stamp(file_name: &str, prefix: &str) -> Option<u128> {
275:     let rest = file_name.strip_prefix(prefix)?;
276:     let mut parts = rest.split('-');
277:     parts.next()?; // pid：不参与排序
278:     parts.next()?.parse().ok()
279: }
280: 
281: /// 保留**第一份 + 最近两份**，其余连同 `-wal/-shm/-journal` 一起清掉。
282: ///
283: /// `newest` 是刚隔离出来的那一份，无条件保留（即使它的 stamp 因时钟回拨排不进最新两份）。
284: fn prune_quarantined(newest: &Path, name: &str) {
285:     let Some(dir) = newest.parent() else { return };
286:     let prefix = format!("{name}.corrupt-");
287:     let Ok(entries) = fs::read_dir(dir) else { return };
288:     let mut found: Vec<(u128, PathBuf)> = entries
289:         .flatten()
290:         .filter_map(|entry| {
291:             let file_name = entry.file_name().to_string_lossy().into_owned();
292:             // 附属件跟着主件走，不作为独立候选。
293:             if ["-wal", "-shm", "-journal"]
294:                 .iter()
295:                 .any(|suffix| file_name.ends_with(suffix))
296:             {
297:                 return None;
298:             }
299:             let stamp = quarantine_stamp(&file_name, &prefix)?;
300:             Some((stamp, entry.path()))
301:         })
302:         .collect();
303:     if found.len() <= QUARANTINE_KEEP {
304:         return;
305:     }
306:     // 新 → 旧；同一毫秒按文件名倒序（counter 大的更新）。
307:     found.sort_by(|a, b| {
308:         b.0.cmp(&a.0)
309:             .then_with(|| b.1.file_name().cmp(&a.1.file_name()))
310:     });
311: 
312:     // 保留集：刚隔离的一份 + 最早的一份（首次损坏现场）+ 最新的若干份补足上限。
313:     let mut keep: HashSet<PathBuf> = HashSet::new();
314:     keep.insert(newest.to_path_buf());
315:     if let Some((_, oldest)) = found.last() {
316:         keep.insert(oldest.clone());
317:     }
318:     for (_, path) in found.iter().take(QUARANTINE_KEEP - 1) {
319:         if keep.len() >= QUARANTINE_KEEP {
320:             break;
321:         }
322:         keep.insert(path.clone());
323:     }
324:     for (_, old) in &found {
325:         if keep.contains(old) {
326:             continue;
327:         }
328:         tracing::debug!(path = %old.display(), "清理过旧的损坏索引保留件");
329:         for suffix in ["", "-wal", "-shm", "-journal"] {
330:             let mut candidate = old.as_os_str().to_os_string();
331:             candidate.push(suffix);
332:             let _ = fs::remove_file(PathBuf::from(candidate));
333:         }
334:     }
335: }
