/// 会被压缩锚点取代的档案下标集合（`surface = shadowed`）。
///
/// 序号口径必须与 `rollout::resume` / `lib.rs::project_entries` 完全一致：
/// 只数进入历史序列的条目（消息、调用、**工具输出**、图片），锚点用一条摘要
/// 顶掉 `[range_start, range_end)`——所以这里用一个哨兵值占住摘要那个槽位，
/// 否则后一个锚点的区间会整体错位一格。
fn shadowed_indices(items: &[RolloutItem]) -> HashSet<usize> {
    // 历史槽位：`Some(档案下标)` = 仍在序列里的原始条目，`None` = 摘要顶替出来的槽位
    // （摘要本身是当前内容，不会被标 shadowed）。
    let mut slots: Vec<Option<usize>> = Vec::new();
    let mut shadowed = HashSet::new();
    for (index, item) in items.iter().enumerate() {
        if !is_history_item(item) {
            // 与 `rollout::resume` 一致：只有进入历史序列的条目才占锚点序号。
            // 压缩锚点本身在下面处理；其余审计记录（TurnEnd 等）不占位。
            if let RolloutItem::Compacted { range_start, range_end, .. } = item {
                let (start, end) = (*range_start as usize, *range_end as usize);
                // 越界/倒置的锚点在 `rollout::resume` 里会让整份档案不可续用；
                // 这里没有错误通道（文档抽取是纯函数），保守起见跳过它：
                // 宁可少标几条 shadowed，也不凭空标错。
                if start > end || end > slots.len() {
                    continue;
                }
                for slot in slots.drain(start..end) {
                    if let Some(archive_index) = slot {
                        shadowed.insert(archive_index);
                    }
                }
                slots.insert(start, None);
            }
            continue;
        }
        slots.push(Some(index));
    }
    shadowed
}
```

