181: /// 会被压缩锚点取代的档案下标集合（`surface = shadowed`）。
182: ///
183: /// 序号口径必须与 `rollout::resume` / `lib.rs::project_entries` 完全一致：
184: /// 只数进入历史序列的条目（消息、调用、**工具输出**、图片），锚点用一条摘要
185: /// 顶掉 `[range_start, range_end)`——所以这里用一个哨兵值占住摘要那个槽位，
186: /// 否则后一个锚点的区间会整体错位一格。
187: fn shadowed_indices(items: &[RolloutItem]) -> HashSet<usize> {
188:     // 历史槽位：`Some(档案下标)` = 仍在序列里的原始条目；`None` = 锚点摘要顶替出来的
189:     // 槽位（摘要本身就是当前内容，不会被标 shadowed，但必须占位，否则后一个锚点的
190:     // 区间会整体错一格）。
191:     let mut slots: Vec<Option<usize>> = Vec::new();
192:     let mut shadowed = HashSet::new();
193:     for (index, item) in items.iter().enumerate() {
194:         let RolloutItem::Compacted { range_start, range_end, .. } = item else {
195:             // 与 `rollout::resume` 同口径：只有进入历史序列的条目才占锚点序号。
196:             if is_history_item(&item) {
197:                 slots.push(Some(index));
198:             }
199:             continue;
200:         };
201:         let (start, end) = (*range_start, *range_end);
202:         // 越界/倒置的锚点在 `rollout::resume` 里会让整份档案不可续用；文档抽取是纯函数、
203:         // 没有错误通道，保守起见跳过它——宁可少标几条 shadowed，也不凭空标错。
204:         if start > end || end > slots.len() {
205:             continue;
206:         }
207:         for replaced in slots.drain(start..end) {
208:             if let Some(archive_index) = replaced {
209:                 shadowed.insert(archive_index);
210:             }
211:         }
212:         slots.insert(start, None);
213:     }
214:     shadowed
215: }
